/* Sincronizzazione privata tra dispositivi, autenticata con l'account ChatGPT. */
(()=>{'use strict';const $=s=>document.querySelector(s);let busy=false,queued=false,remote=null;
function panel(){let box=$('#cloudSync');if(!box){box=document.createElement('section');box.id='cloudSync';box.className='notice';box.style.margin='18px 0';$('#backup').prepend(box)}if(!box.dataset.ready){box.innerHTML='<b>Sincronizzazione privata tra dispositivi</b><p id="cloudSyncStatus" role="status">Controllo archivio online…</p><p id="cloudSyncDetail" class="small" aria-live="polite"></p><div class="toolbar"><button class="btn primary" id="cloudSyncAction">Controlla sincronizzazione</button><button class="btn" id="cloudSyncPull" hidden>Usa la copia online</button><button class="btn" id="cloudSyncPush" hidden>Carica questa copia</button></div><p class="small">Usa lo stesso account ChatGPT su telefono e computer. Questa funzione collega i tuoi dispositivi: non crea profili separati per altri utenti. Dati e documenti restano nel tuo spazio privato; non vengono inviati a GitHub. Le copie in conflitto restano conservate sui rispettivi dispositivi.</p>';box.dataset.ready='1'}return box}
function say(s){panel();$('#cloudSyncStatus').textContent=s;let status=$('#syncStatusShortcut'),text=String(s||'');if(status){status.textContent=/^Sincronizzato(?: ·|$)/.test(text)?'Cloud: sincronizzato':/scelta quale archivio|Conflitto:|Le copie non coincidono/i.test(text)?'Cloud: copie diverse':/disponibile una copia online/i.test(text)?'Cloud: scelta necessaria':/non ancora configurato|Attiva la sincronizzazione/i.test(text)?'Cloud: da attivare':/Carico la copia|Ripristino la copia|Sincronizzando/i.test(text)?'Cloud: in corso':/sospesa|non disponibile|non riuscita|in attesa di connessione/i.test(text)?'Cloud: da riallineare':'Cloud: controlla stato';status.setAttribute('aria-label','Stato sincronizzazione: '+text+' Apri Copia e ripristino per gestire le copie.')}}
async function getRemote(){let r=await fetch('/api/sync',{cache:'no-store'});if(!r.ok)throw Error((await r.json().catch(()=>({}))).error||'Archivio cloud non raggiungibile');return r.json()}
async function marker(){return dbGet('state','cloudSync')}
function copyCounts(value){const s=value||{};return `${s.accounts?.length||0} conti · ${s.movements?.length||0} operazioni · ${s.documents?.length||0} documenti · ${s.positions?.length||0} posizioni`}
async function showCopyDetail(remoteCopy=remote,localMarker=null){const m=localMarker??await marker(),files=await dbAllFiles(),localCount=`Questa copia: ${copyCounts(state)} · ${files.length} allegati`;let online=remoteCopy?.exists?`Copia online: ${copyCounts(remoteCopy.state)} · ${remoteCopy.files?.length||0} allegati · revisione ${remoteCopy.revision}`:'Copia online non ancora creata';let last=m?.syncedAt?`Ultima sincronizzazione: ${new Date(m.syncedAt).toLocaleString('it-IT')}`:'Questa copia non ha ancora una sincronizzazione registrata';const node=$('#cloudSyncDetail');if(node)node.textContent=`${localCount}. ${online}. ${last}.`} 
async function setMarker(m){await new Promise((ok,no)=>{let tx=db.transaction('state','readwrite');tx.objectStore('state').put(m,'cloudSync');tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
function setActions({pull=false,push=false,label=''}){panel();$('#cloudSyncPull').hidden=!pull;$('#cloudSyncPush').hidden=!push;$('#cloudSyncAction').textContent=label||'Sincronizza ora'}
async function upload(expected){if(busy)return;busy=true;try{say('Carico la copia privata e gli originali dei documenti…');const files=await dbAllFiles();const list=files.map(f=>({id:f.id,name:f.name}));const prior=new Set(((await marker())?.files||[]).map(f=>f.id));for(const f of files){if(prior.has(f.id))continue;let type=f.blob?.type||'application/octet-stream';let r=await fetch('/api/sync/file?id='+encodeURIComponent(f.id),{method:'PUT',headers:{'content-type':type},body:f.blob});if(!r.ok)throw Error('Un documento non è stato caricato; la copia precedente è conservata')}let r=await fetch('/api/sync',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({expectedRevision:expected,state,files:list})});let result=await r.json();if(r.status===409){remote=await getRemote();await showCopyDetail(remote,await marker());say('Conflitto: l’altro dispositivo ha salvato una versione diversa. Le due copie restano al sicuro. Scegli quale usare.');setActions({pull:true,push:true});return}if(!r.ok)throw Error(result.error||'Sincronizzazione non riuscita');remote={exists:true,revision:result.revision};await setMarker({revision:result.revision,files:list,syncedAt:new Date().toISOString()});await showCopyDetail(remote,await marker());say('Sincronizzato. La copia online è aggiornata.');setActions({label:'Sincronizza ora'})}catch(e){say('Sincronizzazione sospesa: '+e.message+'. I dati su questo dispositivo restano salvati.');setActions({label:'Riprova'})}finally{busy=false;if(queued){queued=false;afterCommit()}}}
async function pull(){if(busy||!remote?.exists)return;const filesBefore=await dbAllFiles();if(!confirm(`Usare la copia online su questo dispositivo?\n\nOnline: ${copyCounts(remote.state)} · ${remote.files?.length||0} allegati\nQui: ${copyCounts(state)} · ${filesBefore.length} allegati\n\nLa copia locale verrà sostituita. Prima ne creo un punto di sicurezza recuperabile. Le due copie online e locale non vengono unite.`))return;busy=true;try{if(typeof saveRestoreSafetyPoint==='function')await saveRestoreSafetyPoint();say('Ripristino la copia online su questo dispositivo…');const files=[];for(const item of remote.files||[]){const r=await fetch('/api/sync/file?id='+encodeURIComponent(item.id));if(!r.ok)throw Error('Un documento originale non è disponibile; nessun dato è stato sostituito');files.push({id:item.id,name:item.name,blob:await r.blob()})}await commit(remote.state,files,{replaceFiles:true,skipDuplicateReview:true,skipCloud:true});await setMarker({revision:remote.revision,files:remote.files||[],syncedAt:new Date().toISOString()});await showCopyDetail(remote,await marker());say('Ripristino completato. Questo dispositivo è sincronizzato. La copia precedente si può recuperare da Copia e ripristino.');setActions({label:'Sincronizza ora'})}catch(e){say('Ripristino non completato: '+e.message)}finally{busy=false}}
async function check(){panel();try{remote=await getRemote();let m=await marker();await showCopyDetail(remote,m);if(!remote.exists){say('Archivio online non ancora configurato. Attiva la sincronizzazione dal dispositivo che contiene la copia corretta: verranno caricati i conti e i documenti presenti qui.');setActions({label:'Attiva sincronizzazione'});return}if(m?.revision===remote.revision){if(JSON.stringify(state)===JSON.stringify(remote.state)){say('Sincronizzato · revisione '+remote.revision);setActions({label:'Sincronizza ora'});return}await upload(remote.revision);return}say('È disponibile una copia online (revisione '+remote.revision+'). Se questo dispositivo contiene dati propri, scegli quale archivio mantenere.');setActions({pull:true,push:true})}catch(e){say('Connessione cloud non disponibile: '+e.message+'. L’archivio locale continua a funzionare.');setActions({label:'Riprova'})}}
async function action(){if(busy)return;try{remote=await getRemote();let m=await marker();if(remote.exists&&m?.revision!==remote.revision){await showCopyDetail(remote,m);say('Le copie non coincidono. Controlla i riepiloghi qui sopra: “Usa la copia online” sostituisce questo dispositivo; “Carica questa copia” aggiorna quella online. Il dispositivo che non scegli conserva la sua copia.');setActions({pull:true,push:true});return}if(!remote.exists){const files=await dbAllFiles();if(!confirm('Creare la copia privata online con i dati di questo dispositivo?\n\n'+state.accounts.length+' conti · '+state.movements.length+' operazioni · '+files.length+' documenti allegati\n\nProcedi solo se questa è la copia che vuoi usare su telefono e computer.'))return;}await upload(remote.revision||0)}catch(e){say('Sincronizzazione non riuscita: '+e.message)}}
async function afterCommit(){if(busy){queued=true;return}const m=await marker();if(!m?.revision)return;try{const now=await getRemote();if(!now.exists||now.revision!==m.revision){remote=now;say('Modifiche conservate su questo dispositivo. Un altro dispositivo ha aggiornamenti da confrontare.');setActions({pull:!!now.exists,push:!!now.exists});return}await upload(m.revision)}catch(e){say('Modifiche salvate localmente; sincronizzazione in attesa di connessione.') }}
async function filesReplaced(){const m=await marker();if(m)await setMarker({...m,files:[]});await afterCommit()}
let started=false;function start(){if(started)return;started=true;panel();$('#cloudSyncAction').onclick=action;$('#cloudSyncPull').onclick=pull;$('#cloudSyncPush').onclick=async()=>{if(confirm('Caricare questa copia e sostituire quella online? Il dispositivo conserva comunque la propria copia.')){remote=await getRemote();await showCopyDetail(remote,await marker());await upload(remote.revision||0)}};check()}window.TefinanzaSync={afterCommit,filesReplaced};window.addEventListener('tefinanza-ready',start,{once:true});if(window.tefinanzaIsReady)start();})();
